head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageId = "ULDTMS04030";
scwin.scrollTop = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 서식분류 정보를 동적 서브미션으로 조회해 콜백(sbm_upclss_submitdone)을 직접 호출하고, 페이지 리스트를 초기화(숨김)한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = async function () {
    try {
                    // 서식분류 정보 조회
                    const sbmOptions = {
                        id : "sbm_upclss",
                        action : "/api/code/form-upclss",
                        method : "get",
                        processMsg : "공통코드 조회중..."
                    };

                    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);                
                    scwin.sbm_upclss_submitdone(sbmRtn);
                    // 초기화
                    pgl_list.hide();

    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDTMS04030.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
            /**
             * @method
             * @name btn_search_onclick
             * @description [조회] 버튼 클릭 — 목록을 1페이지부터 재조회한다(총건수 포함).
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_search_onclick(e);
             */
            scwin.btn_search_onclick = function (e) {

                scwin.fnSearch("Y", 1);
            };

            /**
             * @method
             * @name sbx_page_onchange
             * @description 한 페이지 건수 변경 — 목록을 1페이지부터 재조회한다(총건수 포함).
             * @param {Object} info 선택 변경 정보 객체
             * @returns {void}
             * @hidden N
             * @example scwin.sbx_page_onchange(info);
             */
            scwin.sbx_page_onchange = function (info) {

                scwin.fnSearch("Y", 1);
            };

            /**
             * @method
             * @name pgl_list_onclick
             * @description 페이지 번호 클릭 — 해당 페이지의 목록을 조회한다(총건수 미조회).
             * @param {Number} index 클릭한 페이지 번호
             * @returns {void}
             * @hidden N
             * @example scwin.pgl_list_onclick(1);
             */
            scwin.pgl_list_onclick = function (index) {

                scwin.fnSearch("N", index);
            };

            /**
             * @method
             * @name ibx_keyword_onkeyup
             * @description 검색어 입력란 키 입력 — Enter 키 입력 시 목록을 1페이지부터 재조회한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.ibx_keyword_onkeyup(e);
             */
            scwin.ibx_keyword_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch("Y", 1);
                }
            };

            /**
             * @method
             * @name btn_excel_onclick
             * @description [엑셀다운로드] 버튼 클릭 — 검색 조건으로 유형분류 엑셀 다운로드를 요청한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_excel_onclick(e);
             */
            scwin.btn_excel_onclick = function (e) {

                // 파라미터 처리
                const url = "/api/code/type-clss/excel";                
                $c.tms.downloadProc(url, dma_search.getJSON());                
            };

            /**
             * @method
             * @name btn_insert_onclick
             * @description [등록] 버튼 클릭 — 유형분류 등록 팝업을 열고, 등록 완료(refreshYn "Y") 시 목록을 1페이지부터 재조회한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.btn_insert_onclick(e);
             */
            scwin.btn_insert_onclick = async function (e) {

                const result = await scwin.fnPopUp("유형분류 등록", {});
                if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {
                    scwin.fnSearch("Y", 1);
                }
            };

            /**
             * @method
             * @name grd_list_oncellclick
             * @description 목록 셀 클릭 — 변경(update) 버튼 클릭 시 그리드 위치 저장 후 변경 팝업을 열어 저장 완료 시 기존 페이지 기준으로 재조회하고, 삭제(delete) 버튼 클릭 시 확인 후 삭제(sbm_del)를 실행한다.
             * @param {Number} rowIndex 클릭한 행 인덱스
             * @param {Number} columnIndex 클릭한 컬럼 인덱스
             * @param {String} columnId 클릭한 컬럼 ID
             * @returns {void}
             * @hidden N
             * @example scwin.grd_list_oncellclick(0, 5, "update");
             */
            scwin.grd_list_oncellclick = async function (rowIndex, columnIndex, columnId) {

                if (columnId === "update") {
                    const params = {};
                    params.formUpclssCd = dlt_list.getCellData(rowIndex, "formUpclssCd");
                    params.tpClssCd = dlt_list.getCellData(rowIndex, "tpClssCd");
                    params.ldMktTpCd = dlt_list.getCellData(rowIndex, "ldMktTpCd");
                    params.disclsTpClssNm = dlt_list.getCellData(rowIndex, "disclsTpClssNm");
                    params.disclsTpClssEngNm = dlt_list.getCellData(rowIndex, "disclsTpClssEngNm");
                    params.storageId = scwin.pageId;

                    // 위치 정보 저장
                    $c.tms.setKeywordSave(scwin.pageId, grd_list, dma_search);

                    const result = await scwin.fnPopUp("유형분류 변경", params);
                    if (!$c.util.isEmpty(result) && result.refreshYn === "Y") {
                        let page = 1;
                        let refreshYn = "Y";
                        if (!$c.util.isEmpty(result.storageId)) {
                            scwin.scrollTop = $c.tms.getKeywordSave(result.storageId, dma_search);

                            if (dma_search.get("page") !== "") {
                                page = dma_search.get("page");
                                refreshYn = "N";
                            }
                        }  
                        scwin.fnSearch(refreshYn, page);
                    } else {
                        $c.tms.delKeyword(scwin.pageId);
                    }
                } else if (columnId === "delete") {
                    if (await $c.win.confirm("삭제 하시겠습니까?")) {                     
                        $c.sbm.setAction(sbm_del, "/api/code/type-clss/delete/" + dlt_list.getCellData(rowIndex, "formUpclssCd") + "/" + dlt_list.getCellData(rowIndex, "tpClssCd") + "/" + dlt_list.getCellData(rowIndex, "ldMktTpCd"));                    
                        $c.sbm.execute(sbm_del);
                    }
                }
            };

///////// 4. 서브미션 콜백 영역 /////////
            /**
             * @method
             * @name sbm_upclss_submitdone
             * @description 서식분류 조회 콜백 — 서식대분류 셀렉트박스를 구성하고 목록을 최초 조회한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example scwin.sbm_upclss_submitdone(sbmRtn);
             */
            scwin.sbm_upclss_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // select box 자동 생성
                    $c.tms.setSelectData(result.body, sbx_formUpclssCd, "formUpclssNm", "formUpclssCd");                    
                    // 편의상 바로 조회
                    scwin.fnSearch("Y", 1);
                } else {
                    $c.win.alert(result.message);
                }                                                    
            };

            /**
             * @method
             * @name sbm_list_submitdone
             * @description 목록 조회(sbm_list) 콜백 — 최초 조회 시에만 총건수·페이지 리스트를 표시하고, 저장된 스크롤 위치가 있으면 복원한다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (sbm_list ev:submitdone 바인딩으로 자동 호출)
             */
            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    const obj = result.body;
                    const firstYn = dma_search.get("totalYn");
                    let totalCnt = 0;

                    // 최초 조회일 경우에만 전체 건수를 구하여 전역변수에 담는다.
                    if (firstYn === "Y") {
                        if (!$c.util.isEmpty(obj.totalCount)) {
                            tbx_totCnt.setValue($c.num.formatNumber(obj.totalCount));
                            totalCnt = parseInt(obj.totalCount) || 0;
                        }        

                        // 데이터가 있는 경우에만 페이지 리스트 표시
                        if (totalCnt > 0) { 
                            pgl_list.setCount(obj.totalPages);
                            pgl_list.show();
                        } else {
                            pgl_list.hide();
                        }            
                    }

                    // 재조회 여부 체크
                    if (!$c.util.isEmpty(scwin.scrollTop)) {
                        grd_list.setScrollTop(scwin.scrollTop);                        
                        scwin.scrollTop = "";
                    }                    
                } else {
                    $c.win.alert(result.message);
                }               
            };

            /**
             * @method
             * @name sbm_del_submitdone
             * @description 삭제(sbm_del) 콜백 — 성공 시 완료 알림 후 목록을 1페이지부터 재조회하고, 실패 시 오류 메시지를 알린다.
             * @param {Object} e 이벤트 객체
             * @returns {void}
             * @hidden N
             * @example (sbm_del ev:submitdone 바인딩으로 자동 호출)
             */
            scwin.sbm_del_submitdone = async function (e) {

                const result = e.responseJSON;
                if (result.success) {
                    await $c.win.alert("삭제 되었습니다.");
                    scwin.fnSearch("Y", 1);
                } else {
                    $c.win.alert(result.message);
                }
            };

///////// 5. 일반/업무 함수 영역 /////////
            /**
             * @method
             * @name fnSearch
             * @description 목록 조회 — 총건수 조회 여부·페이지 번호·한 페이지 건수를 dma_search 에 설정하고 목록(sbm_list)을 조회한다.
             * @param {String} totYn 총건수 조회 여부("Y"/"N")
             * @param {Number} index 조회할 페이지 번호
             * @returns {void}
             * @hidden N
             * @example scwin.fnSearch("Y", 1);
             */
            scwin.fnSearch = function (totYn, index) {

                dma_search.set("totalYn", totYn);
                dma_search.set("page", index);
                dma_search.set("size", sbx_page.getValue());

                // 조회 
                $c.sbm.execute(sbm_list, dma_search.getJSON());
            };

            /**
             * @method
             * @name fnButtonUpdateHtml
             * @description 그리드 변경(update) 컬럼 커스텀 포매터 — [변경] 버튼 HTML 을 반환한다.
             * @param {String} data 셀 데이터
             * @param {String} formattedData 포맷 적용된 셀 데이터
             * @param {Number} rowIndex 행 인덱스
             * @param {Number} columnIndex 컬럼 인덱스
             * @returns {String} 버튼 HTML 문자열
             * @hidden N
             * @example (grd_list update 컬럼 customFormatter 바인딩으로 자동 호출)
             */
            scwin.fnButtonUpdateHtml = function (data, formattedData, rowIndex, columnIndex) {

                return "<button class='btn-edit'>변경</button>";
            };

            /**
             * @method
             * @name fnButtonDeleteHtml
             * @description 그리드 삭제(delete) 컬럼 커스텀 포매터 — [삭제] 버튼 HTML 을 반환한다.
             * @param {String} data 셀 데이터
             * @param {String} formattedData 포맷 적용된 셀 데이터
             * @param {Number} rowIndex 행 인덱스
             * @param {Number} columnIndex 컬럼 인덱스
             * @returns {String} 버튼 HTML 문자열
             * @hidden N
             * @example (grd_list delete 컬럼 customFormatter 바인딩으로 자동 호출)
             */
            scwin.fnButtonDeleteHtml = function (data, formattedData, rowIndex, columnIndex) {

                return "<button class='btn-del' style='color:red;'>삭제</button>";
            };

            /**
             * @method
             * @name fnPopUp
             * @description 유형분류 등록/변경 팝업(ULDTMS04040)을 연다.
             * @param {String} title 팝업 타이틀
             * @param {Object} params 팝업 전달 파라미터
             * @returns {Promise} openPopup 결과 Promise(팝업 종료 시 전달받는 객체)
             * @hidden N
             * @example const result = await scwin.fnPopUp("유형분류 등록", {});
             */
            scwin.fnPopUp = function (title, params) {

                const url_ = "/ui/TMS/ULDTMS04040.xml";
                const options = {
                    id: "ULDTMS04040_POP",
                    popupName: title,
                    width: "670",
                    height: "330",
                    frameModal: "top"
                };
                return $c.win.openPopup(url_, options, params);              
            }
